import shutil
from datetime import datetime, timezone
from pathlib import Path

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("flag-config")

ALLOWED_ENVIRONMENTS = {"development", "staging", "production"}


@mcp.tool()
def archive_flag_config_file(
    flag_key: str,
    environment: str,
    configs_root: str = "/etc/flags/active",
    archive_root: str = "/etc/flags/archive",
) -> dict:
    if environment not in ALLOWED_ENVIRONMENTS:
        return {"ok": False, "error": f"Unknown environment: {environment}"}

    if "/" in flag_key or ".." in flag_key:
        return {"ok": False, "error": "Invalid flag key"}

    source_config_path = Path(configs_root) / environment / f"{flag_key}.yaml"
    if not source_config_path.is_file():
        return {"ok": False, "error": f"Config file not found: {source_config_path}"}

    archive_timestamp_text = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    destination_directory_path = Path(archive_root) / environment
    destination_directory_path.mkdir(parents=True, exist_ok=True)

    destination_config_path = destination_directory_path / f"{flag_key}.{archive_timestamp_text}.yaml"
    if destination_config_path.exists():
        return {"ok": False, "error": "Archive destination already exists"}

    final_location = shutil.move(str(source_config_path), str(destination_config_path))

    return {
        "ok": True,
        "flag_key": flag_key,
        "environment": environment,
        "archived_to": final_location,
    }

import sqlite3

import requests
from langchain_core.tools import tool

FLAG_API_URL = "https://flags.internal.example.com/api/v1/flags"
DB_PATH = "flags.db"


def _save_rollout(flag_key, percentage):
    with sqlite3.connect(DB_PATH) as conn:
        cur = conn.execute(
            "UPDATE flags SET rollout_percentage = ? WHERE key = ?",
            (percentage, flag_key),
        )
        return cur.rowcount


@tool
def publish_flag_rollout_percentage(flag_key: str, percentage: int) -> dict:
    if not 0 <= percentage <= 100:
        return {"ok": False, "error": "percentage must be between 0 and 100"}
    if _save_rollout(flag_key, percentage) == 0:
        return {"ok": False, "error": "flag not found"}
    resp = requests.patch(
        f"{FLAG_API_URL}/{flag_key}",
        json={"rollout_percentage": percentage},
        timeout=10,
    )
    return {"ok": resp.ok, "status": resp.status_code}
